-- Dev-only operator transaction. Normal welcome production is stopped before any row becomes visible to workers.
begin;
set local lock_timeout='5s';
set local statement_timeout='55s';
select pg_advisory_xact_lock(hashtextextended('groups-pencil-dev-v1',0));
create temp table fixture_identity_bindings(n integer primary key check(n between 1 and 3),actor uuid not null unique,privy text not null unique,email text not null unique,wallet text not null unique)on commit drop;
insert into fixture_identity_bindings select (x->>'n')::int,('f1610000-0000-4000-8000-'||lpad(x->>'n',12,'0'))::uuid,x->>'privyUserId',x->>'email',x->>'walletAddress' from jsonb_array_elements(current_setting('byus.groups_pencil_identities')::jsonb)x;
do $$declare r record;u public.app_users;begin
 if current_setting('byus.groups_pencil_dev',true)is distinct from'SEED_GROUPS_PENCIL_DEV_ONLY'or(select count(*)from fixture_identity_bindings)<>3 then raise exception 'DEV_FIXTURE_IDENTITY_CONFIRMATION';end if;
 for r in select *from fixture_identity_bindings order by n loop
  select *into u from public.app_users where id=r.actor for update;
  if not found or u.status<>'active' or not ((u.privy_user_id='fixture:groups-pencil-dev:'||r.n and u.verified_email='groups-pencil-dev-'||r.n||'@example.test')or(u.privy_user_id=r.privy and u.verified_email=r.email))then raise exception 'DEV_FIXTURE_IDENTITY_COLLISION';end if;
  if r.privy!~'^did:privy:[A-Za-z0-9:_-]+$'or r.email is null or r.wallet!~'^0x[0-9a-f]{40}$'then raise exception 'DEV_FIXTURE_IDENTITY_INVALID';end if;
  if exists(select 1 from public.app_users where id<>r.actor and(privy_user_id=r.privy or verified_email=r.email))or exists(select 1 from public.admin_allowlist where email=r.email)then raise exception 'DEV_FIXTURE_IDENTITY_ALREADY_OWNED';end if;
  if exists(select 1 from public.user_wallets where(app_user_id=r.actor and(chain_id<>91342 or address<>r.wallet or provider<>'privy' or wallet_type<>'embedded'))or(chain_id=91342 and address=r.wallet and app_user_id<>r.actor))then raise exception 'DEV_FIXTURE_WALLET_COLLISION';end if;
  if exists(select 1 from public.fan_lounge_messages where app_user_id=r.actor)or exists(select 1 from public.celebrity_notice_comments where app_user_id=r.actor)or exists(select 1 from public.fan_posts where app_user_id=r.actor and first_comment_eligible)or exists(select 1 from public.kyaa_wave_participants where app_user_id=r.actor)then raise exception 'DEV_FIXTURE_RECOVERY_HISTORY';end if;
  if u.privy_user_id<>r.privy and(exists(select 1 from public.user_wallets where app_user_id=r.actor)or exists(select 1 from public.community_stamps where app_user_id=r.actor)or exists(select 1 from public.fan_action_occurrences where app_user_id=r.actor))then raise exception 'DEV_FIXTURE_EXISTING_ACTIVITY';end if;
  if exists(select 1 from public.community_stamps where app_user_id=r.actor and(kind<>'welcome'or mint_status<>'permanent_failure'))then raise exception 'DEV_FIXTURE_STAMP_STATE';end if;
 end loop;
end $$;
create temp table fixture_existing_stamps on commit drop as select s.id from public.community_stamps s join fixture_identity_bindings b on b.actor=s.app_user_id;
update public.app_users u set privy_user_id=b.privy,verified_email=b.email from fixture_identity_bindings b where u.id=b.actor and(u.privy_user_id<>b.privy or u.verified_email is distinct from b.email);
insert into public.user_wallets(app_user_id,chain_id,address,provider,wallet_type)select actor,91342,wallet,'privy','embedded'from fixture_identity_bindings on conflict(app_user_id,chain_id)do nothing;
-- Only new welcome jobs generated by this transaction are stopped. Existing jobs are never rewritten.
update public.blockchain_jobs j set status='FAILED',last_error_code='DEV_FIXTURE_NO_BROADCAST',last_error_message='Dev fixture only. Do not retry or broadcast.'
 from public.community_stamps s,fixture_identity_bindings b where s.app_user_id=b.actor and s.kind='welcome'and j.id=s.blockchain_job_id and not exists(select 1 from fixture_existing_stamps x where x.id=s.id);
update public.fan_action_outbox j set status='FAILED',last_error_code='DEV_FIXTURE_NO_BROADCAST',last_error_message='Dev fixture only. Do not retry or broadcast.'
 from public.community_stamps s,fixture_identity_bindings b where s.app_user_id=b.actor and s.kind='welcome'and j.id=s.fan_action_outbox_id and not exists(select 1 from fixture_existing_stamps x where x.id=s.id);
do $$declare r record;stamp_count integer;jobs_before integer;outbox_before integer;begin
 for r in select *from fixture_identity_bindings loop
  if exists(select 1 from public.blockchain_jobs j where j.payload->>'recipient'=r.wallet and not exists(select 1 from public.community_stamps s where s.app_user_id=r.actor and s.kind='welcome'and s.blockchain_job_id=j.id))or exists(select 1 from public.fan_action_outbox j join public.fan_action_occurrences o on o.id=j.occurrence_row_id where o.app_user_id=r.actor and not exists(select 1 from public.community_stamps s where s.app_user_id=r.actor and s.kind='welcome'and s.fan_action_outbox_id=j.id))then raise exception 'DEV_FIXTURE_UNEXPECTED_JOB';end if;
  select count(*)into stamp_count from public.community_stamps where app_user_id=r.actor and kind='welcome'and mint_status='permanent_failure'and tx_hash is null and token_id is null;
  if stamp_count<>1 then raise exception 'DEV_FIXTURE_WELCOME_MISSING';end if;
  if exists(select 1 from public.community_stamps s join public.blockchain_jobs j on j.id=s.blockchain_job_id where s.app_user_id=r.actor and(j.status<>'FAILED'or j.last_error_code is distinct from'DEV_FIXTURE_NO_BROADCAST'or j.attempts<>0 or j.tx_hash is not null or j.token_id is not null or j.payload->>'signedTransaction' is not null or j.lease_expires_at is not null or j.lease_owner is not null))or exists(select 1 from public.fan_action_outbox j join public.fan_action_occurrences o on o.id=j.occurrence_row_id where o.app_user_id=r.actor and(j.status<>'FAILED'or j.last_error_code is distinct from'DEV_FIXTURE_NO_BROADCAST'or j.attempts<>0 or j.tx_hash is not null or j.signed_transaction is not null or j.lease_owner is not null))then raise exception 'DEV_FIXTURE_EXECUTABLE_JOB';end if;
  select count(*)into jobs_before from public.blockchain_jobs where payload->>'recipient'=r.wallet;
  select count(*)into outbox_before from public.fan_action_outbox j join public.fan_action_occurrences o on o.id=j.occurrence_row_id where o.app_user_id=r.actor;
  perform public.sync_privy_identity(r.privy,r.email,91342,r.wallet);
  perform public.sync_privy_identity(r.privy,r.email,91342,r.wallet);
  if jobs_before<>(select count(*)from public.blockchain_jobs where payload->>'recipient'=r.wallet)or outbox_before<>(select count(*)from public.fan_action_outbox j join public.fan_action_occurrences o on o.id=j.occurrence_row_id where o.app_user_id=r.actor)then raise exception 'DEV_FIXTURE_LOGIN_CREATED_JOB';end if;
 end loop;
end $$;
select jsonb_build_object('boundAccounts',3,'broadcastableJobs',0,'manualRetryBlocked',false);
commit;
